/**
 * Absolute path to the provider entries shipped inside THIS package.
 *
 * Resolved relative to this module, not to the repository, because the two
 * are only the same place during development. The entries used to live at the
 * repo root while `@celo/buy` and `@celo/buy-registry` both published `dist`
 * alone, so `npm pack` left them behind entirely: a global install got a
 * `buy skills list` that could not find a registry unless the user set
 * BUY_REGISTRY by hand.
 *
 * `../providers` is correct from both `src/` and `dist/` — the two sit at the
 * same depth inside the package — so this does not need a build step or a
 * dev/prod branch.
 */
export declare function bundledRegistryDir(): string;
